<?php require __DIR__.'/bootstrap.php';$token=(string)($_GET['token']??$_POST['token']??'');$booking=null;$error='';$ok='';if($token){try{$svc=new \Islem\Extension\CustomerBooking(db());$booking=$svc->lookup($token);if(!$booking)$error='Lien invalide ou expiré';if($booking&&($_SERVER['REQUEST_METHOD']??'')==='POST'){verify_csrf();$svc->requestChange($token,(string)($_POST['message']??''));$ok='Votre demande de modification a été transmise. Elle sera examinée par l’administration.';}}catch(Throwable $ex){$error='Suivi temporairement indisponible.';}}?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suivi · ISLEM VTC</title><link rel="stylesheet" href="/assets/style.css"></head><body><header class="site-header"><div class="shell nav"><a class="brand" href="/">ISLEM VTC</a><a href="/">Accueil</a></div></header><main class="interior shell"><div class="panel" style="max-width:720px;margin:auto"><h1>Suivre votre réservation</h1><?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?><?php if($ok): ?><div class="success"><?= e($ok) ?></div><?php endif; ?><?php if($booking): ?><h2>Réservation <?= e($booking['booking_code']) ?></h2><p>De <?= e($booking['pickup_address']) ?> à <?= e($booking['dropoff_address']) ?></p><p>Statut : <strong><?= e($booking['status']) ?></strong></p><h3>Demander une modification</h3><form method="post"><input type="hidden" name="token" value="<?= e($token) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><div class="field"><label>Votre demande</label><textarea name="message" minlength="5" maxlength="2000" required rows="4"></textarea></div><button class="btn">Envoyer la demande</button></form><?php else: ?><p class="muted">Utilisez le lien personnel reçu à la confirmation de votre réservation pour consulter son état.</p><?php endif; ?></div></main></body></html>